L000048	\title{Exceptional Point Superradiant Lasing with Ultranarrow Linewidth }
L000049	\author{Min Du}
L000050	\affiliation{School of Physics and Institute for Quantum Science and Engineering, Huazhong University of Science and Technology, and Wuhan Institute of Quantum Technology, Wuhan 430074, China}
L000051	
L000052	\author{Qian Bin}\email{qianbin@scu.edu.cn}
L000053	\affiliation{College of Physics, Sichuan University, Chengdu 610065, China}
L000054	
L000055	\author{Qing-Yang Qiu}
