L000058	\author{Franco Nori}
L000059	\affiliation{Theoretical Quantum Physics Laboratory, Cluster for Pioneering Research, RIKEN, Wako-shi, Saitama 351-0198, Japan}
L000060	\affiliation{Quantum Information Physics Theory Research Team, Quantum Computing Center, RIKEN, Wakoshi, Saitama, 351-0198, Japan}
