L000589	\section{Approximate analytical expression of spectrum linewidth obtained by the quantum regression theorem} \label{III}
L000590	In this section, we derive an analytical expression for the laser linewidth using the quantum regression theorem. The  linewidth $\Delta\nu$ can be obtained from the full width at half maximum\,(FWHM)\,of the laser power spectrum $S(\omega)$, which is related to the two-time correlation function $\langle a^{\dagger}(t)a(0)\rangle$ of the light field
L000591	\begin{equation}
L000592		S(\omega)=2\int_{0}^{\infty} \mathrm{Re}[\langle a^{\dagger}(t)a(0)\rangle e^{-i(\omega-\omega_{a})t}]\,dt.
L000593	\end{equation}
L000594	To obtain $\langle a^{\dagger}(t)a(0)\rangle$, we derive the following equations of motion using the quantum regression theorem
L000595	
L000596	\begin{eqnarray}
L000597		\frac{d}{dt}\langle a^{\dagger}(t)a(0)\rangle&=&(-\frac{1}{2}\kappa_{a}+i\Delta_{a})\langle a^{\dagger}(t)a(0)\rangle+iNg\langle\sigma_{1}^{+}(t)a(0)\rangle+iG\langle b^{\dagger}(t)a(0)\rangle,\\
L000598		\frac{d}{dt}\langle
L000599		\sigma_{1}^{+}(t)a(0)\rangle&=&-\frac{1}{2}(\gamma+\gamma_{\phi}+\eta)\langle\sigma_{1}^{+}(t)a(0)\rangle+ig\langle a^{\dagger}(t)a(0)\rangle-2ig\langle \sigma_{1}^{+}\sigma_{1}^{-}\rangle \langle a^{\dagger}(t)a(0)\rangle,\\
L000600		\frac{d}{dt}\langle b^{\dagger}(t)a(0)\rangle&=&iG\langle a^{\dagger}(t)a(0)\rangle+(i\Delta_{b} -\frac{1}{2}\kappa_{b})\langle b^{\dagger}(t)a(0)\rangle.
L000601	\end{eqnarray}
L000602	
L000603	Considering second-order approximation and factorizing  $\langle a^{\dagger}(t)a(0)\sigma_{1}^{+}(t)\sigma_{1}^{-}(t)\rangle\approx\langle\sigma_{1}^{+}(t)\sigma_{1}^{-}(t)\rangle \langle a^{\dagger}(t)a(0)\rangle$, we can obtain a closed set of equations of motion
L000604	\begin{equation}
L000605		\frac{d}{dt}R(t)=\mathbb{T}\cdot R(t),\label{S20}
L000606	\end{equation}
L000607	
L000608	where
L000609	
L000610	\begin{equation}
L000611		R(t)=(\langle a^{\dagger}(t)a(0)\rangle,\langle\sigma_{1}^{+}(t)a(0)\rangle,\langle b^{\dagger}(t)a(0)\rangle)^{T},
L000612	\end{equation}
L000613	
L000614	and
L000615	
L000616	\begin{eqnarray}
L000617		\mathbb{T}=-\frac{1}{2}\begin{pmatrix}
L000618			-\frac{1}{2}\kappa_{a}+i\Delta_{a}& \qquad  iNg &\qquad iG \\
L000619			ig-2ig\langle\sigma_{1}^{+}\sigma_{1}^{-}\rangle &\qquad -\frac{1}{2}(\gamma+\gamma_{\phi}+\eta) &\qquad 0 \\
L000620			iG                                  &\qquad 0 &\qquad i\Delta_{b}-\frac{1}{2}\kappa_{b}
L000621		\end{pmatrix}.
L000622	\end{eqnarray}
L000623	
L000624	The initial conditions for Eq. (\ref{S20}) are the steady-state solutions of the operators given in Section \ref{II}.
L000625	
L000626	Since the matrix $\mathbb{T}$ is non-Hermitian, its eigenvalues are generally complex, and its eigenvectors are biorthogonal. To solve the dynamic equation Eq. (\ref{S20}), we introduce the left and right eigenvectors of $\mathbb{T}$ as
L000627	\begin{eqnarray}
L000628		\mathbb{T} |i\rangle =\lambda_{i}|i\rangle,\\
L000629		\langle\tilde{i}|\mathbb{T} =\lambda_{i}\langle\tilde{i}|,
L000630	\end{eqnarray}
L000631	where $\lambda_{i} (i=1,2,3)$ are the eigenvalues of $\mathbb{T}$, and $\langle \tilde{i}|$ and $|i\rangle$ are the left and right eigenvectors of $\mathbb{T}$, satisfying the biorthogonal relation $\langle \tilde{i}|j\rangle=\delta_{i,j}$ for $i,j=1,2,3$. The identity operator can then be expressed as $I=\sum_{i}|i\rangle\langle \tilde{i}|$.
L000632	
L000633	Applying the Laplace transform to Eq. (\ref{S20}) gives
L000634	
L000635	\begin{equation}
L000636		\overline{R(p)}=\frac{1}{p-\mathbb{T}}R(0), \label{S25}
L000637	\end{equation}
L000638	
L000639	where $\overline{R(p)}$ is the Laplace transform of $R(t)$.  By inserting the operator $I=\sum_{i}|i\rangle\langle \tilde{i}|$ into Eq. (\ref{S25}), we can obtain
L000640	
L000641	\begin{equation}
L000642		\overline{R(p)}=\sum_{i}\frac{1}{p-\lambda_{i}}|i\rangle\langle\widetilde{i}|R(0).
L000643	\end{equation}
L000644	
L000645	Performing the inverse Laplace transform on this equation, we find
L000646	
L000647	\begin{equation}
L000648		R(t)=\sum_{i}e^{\lambda_{i}t}|i\rangle\langle\widetilde{i}|R(0). \label{S27}
L000649	\end{equation}
L000650	
L000651	From Eq. (\ref{S27}), we see that the two-time correlation function $\langle a^{\dagger}(t)a(0)\rangle$ is a superposition of the functions $e^{\lambda_{i}t}(i=1,2,3)$. After applying the Fourier transform to the correlation function, the laser spectrum can be derived as
L000652	
L000653	\begin{eqnarray} \label{S31-0}
L000654		S(\omega)&=&2\sum_{i}\int_{0}^{\infty}dt\mathrm{Re}[C_{i}e^{\mathrm{Re}(\lambda_{i})t}e^{-i(\omega-\omega_{a}-\mathrm{Im}(\lambda_{i}))t}]\nonumber\\&=&\sum_{i} C_{i}\frac{2\mathrm{Re}(\lambda_{i})}{[\omega-(\omega_{a}+\mathrm{Im}(\lambda_{i}))]^{2}+(\mathrm{Re}(\lambda_{i}))^{2}},
L000655	\end{eqnarray}
L000656	
L000657	where $S(\omega)$ is a superposition of three Lorentzian line shapes with central frequencies $\omega_{a}+\mathrm{Im}(\lambda_{i})$ and linewidths $2|\mathrm{Re}(\lambda_{i})|$ for $i=1,2,3$.
L000658	
L000659	By solving the eigenfunction of $\mathbb{T}$ to first order, we obtain an approximate expression for the linewidth
L000660	
L000661	\begin{eqnarray}
L000662		\Delta\nu	=	2|\mathrm{Re}(\lambda_{i})|=\frac{(4G^{2}+\kappa_{a}\kappa_{b})(\gamma_{\phi}+\eta+\gamma)+4g^{2}N\kappa_{b}(1-2\langle\sigma_{1}^{+}\sigma_1^{-}\rangle)}{4G^{2}+(\kappa_{a}+\kappa_{b})(\gamma_{\phi}+\eta+\gamma)+\kappa_{a}\kappa_{b}+4g^{2}N(1-2\langle\sigma_{1}^{+}\sigma_1^{-}\rangle)}.
L000663		\label{S29}
L000664	\end{eqnarray}
L000665	
L000666	Substituting $\Gamma=\eta+\gamma_{\phi}+\gamma$, $\Gamma_c=4g^2\kappa_b/(4G^2+\kappa_a\kappa_b)$, and $\langle J_z\rangle/\hbar=N(\langle\sigma_1^{+}\sigma_1^{-}\rangle-1/2)$ into the Eq. (\ref{S29}), we can further simplify
L000667	
L000668	\begin{eqnarray}
L000669		\Delta\nu   &=& \frac{\Gamma+{4g^{2}N\kappa_{b}}(1-2\langle\sigma_{1}^{+}\sigma_1^{-}\rangle)/(4G^{2}+\kappa_{a}\kappa_{b})}{1+(\kappa_{a}+\kappa_{b})\Gamma/(4G^{2}+\kappa_{a}\kappa_{b})+4g^{2}N(1-2\langle\sigma_{1}^{+}\sigma_1^{-}\rangle)/(4G^{2}+\kappa_{a}\kappa_{b})}
L000670		\nonumber\\	&=&	\frac{\Gamma+N\Gamma_{c}[1-2(\langle J_z\rangle/(\hbar N)+1/2)]}{1+(\kappa_{a}+\kappa_{b})\Gamma/(4G^{2}+\kappa_{a}\kappa_{b})+4g^{2}N[1-2(\langle J_z\rangle/(\hbar N)+1/2)]/(4G^{2}+\kappa_{a}\kappa_{b})}
L000671		\nonumber\\&=&\frac{\Gamma-2\Gamma_{c}\langle J_z \rangle/\hbar}{1+(\kappa_{a}+\kappa_{b})\Gamma/(4G^{2}+\kappa_{a}\kappa_{b})-2\langle J_z \rangle\Gamma_{c}/(\hbar\kappa_{b})}.\label{S31}
L000672	\end{eqnarray}
L000673	The above Eq.\,(\ref{S31}) is Eq.\,(6) in the main text.
L000674	Substituting the EP condition $G=G_{\mathcal{PT}}=(\kappa_b-\kappa_a)/4$ into $\Gamma_c$ and $\Delta\nu$ in Eq. (\ref{S31}),  we obtain the linewidth at the EP
L000675	
L000676	\begin{eqnarray}
L000677		\Delta\nu &=&
L000678		\frac{\Gamma-2\Gamma_c\langle J_z \rangle/\hbar}{1+4\Gamma/(\kappa_a+\kappa_b)-2\langle J_z \rangle \Gamma_c/(\hbar\kappa_b)},\label{47}
L000679	\end{eqnarray}
L000680	
L000681	where $\Gamma_c=16g^2\kappa_b/(\kappa_a+\kappa_b)^2$.
L000682	
L000683	\begin{figure}
L000684		\centering
L000685		\includegraphics[width=13.5cm]{sv3.pdf}
L000686		\caption{Emission linewidth $\Delta\nu$ at the EP versus cavity dissipations $\kappa_a$, $\kappa_b$, and the coupling strength $g$ for $\eta/2\pi=10\,\mathrm{Hz}$. For clearer visualization, panels (b)-(d) present special cuts along selected directions: (b) $g/2\pi=0.5\,\mathrm{Hz}$, (c) $\kappa_a/2\pi=1.59\,\mathrm{MHz}$, and (d) $\kappa_b/2\pi=0.14\,\mathrm{MHz}$. The white solid lines correspond to a linewidth of $10^{-5}\,\mathrm{Hz}$.}\label{sv3}
L000687	\end{figure}
L000688	
L000689	Equation\,(\ref{47}) shows that, in addition to the intrinsic system parameters, the linewidth at the EP is affected by $\Gamma$ and $\langle J_z\rangle$. The formula is highly complex, making it difficult to analytically determine the fundamental limit. Therefore, within experimentally feasible parameter ranges, we numerically discuss the minimum value of linewidth $\Delta\nu$ by investigating the effects of the dissipation rates $\kappa_a$,  $\kappa_b$ and the atom–cavity coupling strength $g$. As shown in Fig.\,3(b) of the main text, the linewidth at the EP decreases and then increases with increasing the incoherent pumping. This behavior arises from the corresponding growth and reduction of atom–atom correlations, shown in Fig.\,2(b) of the main text. In our analysis, we set $\eta=10\,\mathrm{Hz}$, close to the value that maximizes atomic coherence and minimizes the linewidth.
L000690	
L000691	Under the condition of $\eta=10\,\mathrm{Hz}$, Figure\,\ref{sv3}(a) depicts the linewidth at the EP as a function of $\kappa_a$, $\kappa_b$, and $g$. The results reveal that, by appropriately selecting the coupling and dissipation strengths at the EP, the linewidth can be maintained at approximately $2\pi \times 10^{-6}\,\mathrm{Hz}$. To visualize it, we extract from Fig.\,\ref{sv3}(a) the parameter points that both yield the minimal linewidth and satisfy  the bad-cavity condition $\kappa_a, \kappa_b \gg g\sqrt{N}$ ($g/2\pi=0.5\,\mathrm{Hz}$, $\kappa_a/2\pi=1.59\,\mathrm{MHz}$, $\kappa_b/2\pi=0.14\,\mathrm{MHz}$). Figures\,\ref{sv3}(b)-\ref{sv3}(d) show two-dimensional cross sections around three points. Figure\,\ref{sv3}(b) shows that although the bad-cavity regime requires large cavity dissipation, increasing $\kappa_{a,b}$ indefinitely broadens the linewidth. This is because the cooperativity $C=4g^2/(\kappa_{\mathrm{eff}}\gamma)$, which quantifies the relative strength of the atom–cavity coupling compared with dissipative processes, decreases as the cavity dissipation increases. When $C$ becomes too small, atom-atom correlations diminish, causing the linewidth to broaden. Figures\,\ref{sv3}(c) and \,\ref{sv3}(d) show that the coupling strength $g$ must lie in an appropriate range. An excessively large $g$ violates the bad-cavity condition $g\sqrt{N} \ll \kappa_a, \kappa_b$, while excessively small $g$ lowers the cooperativity $C$ and reduces atom–atom correlations, again increasing the linewidth. Therefore, by choosing appropriately system parameters $\kappa_a$, $\kappa_b$ and $g$, the minimum linewidth at the EP can be maintained on the order of $10^{-6}\,\mathrm{Hz}$ (corresponding to the areas enclosed by the white curves).
